# Search for 2024 quarters
q2024 = []
found_2024_i = False
for idx, row in df.iterrows():
    val = str(row[0]).strip()
    if val == "2024: I.":
        q2024.append(float(row[1]))
        found_2024_i = True
    elif found_2024_i and val in ["II.", "III.", "III p.", "IV.", "IV p."]:
        q2024.append(float(row[1]))
    elif found_2024_i:
        # If we were in 2024 quarters and hit something else, stop
        if val and not any(q_mark in val for q_mark in ["I.", "II.", "III.", "IV."]):
             break

if q2024:
    data[2024] = sum(q2024) / len(q2024)
    print(f"2024 average for {file_path}: {data[2024]} (from {len(q2024)} quarters: {q2024})")
